window.DCBSettings=(()=>{
 const M=DCBSettingsModel;let ui;
 const titles={user:'ユーザー情報',email:'メールアドレス変更',password:'パスワード変更','card-registration':'カード登録',display:'表示設定',about:'アイカツDCBについて',terms:'利用規約'};
 const title=view=>titles[view]||'設定';
 const parent=view=>['email','password'].includes(view)?'#settings/user':view==='terms'?'#settings/about':'#settings';
 const row=(label,target,disabled=false)=>`<button type="button" class="settings-row" ${disabled?'disabled':`data-settings-go="${target}"`}>${disabled?DCBUI.icon('lock'):''}<span>${label}</span>${disabled?'':DCBUI.icon('chevron')}</button>`;
 const action=(label,target,role='secondary')=>`<button type="button" class="btn-${role}" data-settings-go="${target}">${label}</button>`;
 function top(){return `<div class="settings-list">${row('ユーザー情報','user')}${row('カード登録','card-registration')}${row('表示設定','display')}${row('バックアップ（開発中）','',true)}${row('アイカツDCBについて','about')}</div>`;}
 function user(){const profile=M.profile;return `<div class="settings-field"><div><h2>メールアドレス</h2><p>${profile.email?ui.esc(profile.email):'未設定'}</p></div>${action('変更する','email')}</div><div class="settings-field"><div><h2>ユーザーID</h2><p class="settings-user-id">${profile.id}</p></div><button type="button" class="btn-text btn-icon" data-settings="copy-id" aria-label="ユーザーIDをコピー">${DCBUI.icon('copy','button-icon')}</button></div><div class="settings-list">${row('パスワードを変更','password')}</div><div class="settings-bottom-actions"><button type="button" class="btn-secondary" data-settings="logout">ログイン画面に戻る</button></div>`;}
 function email(){return `<form id="settings-email-form" class="settings-form"><label>新しいメールアドレス<input class="ui-input" name="email" type="email" autocomplete="email" required maxlength="254" value="${ui.esc(M.profile.email)}"></label><p class="settings-error" role="alert" hidden></p><button class="btn-primary" type="submit">変更する</button></form>`;}
 function password(){return `<form id="settings-password-form" class="settings-form"><label>現在のパスワード<input class="ui-input" name="current" type="password" required autocomplete="current-password"></label><label>新しいパスワード<input class="ui-input" name="next" type="password" required autocomplete="new-password"></label><label>新しいパスワード確認<input class="ui-input" name="confirmation" type="password" required autocomplete="new-password"></label><p class="settings-error" role="alert" ${M.canVerifyPassword?'hidden':''}>${M.canVerifyPassword?'':'現在のパスワードを確認するため、ログインし直してください。'}</p><div class="settings-bottom-actions"><button class="btn-primary" type="submit" ${M.canVerifyPassword?'':'disabled'}>変更する</button>${M.canVerifyPassword?'':'<button type="button" class="btn-secondary" data-settings="logout">ログイン画面に戻る</button>'}</div></form>`;}
 function registration(){return `<div class="settings-control"><h2>カード登録モード</h2><label>読み取り後の登録方法<select class="ui-select" id="registration-mode"><option value="confirm" ${DCBRegistration.getMode()==='confirm'?'selected':''}>確認登録（全体を撮影）</option><option value="fast" ${DCBRegistration.getMode()==='fast'?'selected':''}>高速登録（写真なし）</option></select></label></div><div class="settings-control"><label class="settings-control-title" for="bulk-retain-count">保管枚数一括変更</label><select class="ui-select" id="bulk-retain-count">${[1,2,3,4,5].map(n=>`<option value="${n}" ${DCBStore.defaultRetain===n?'selected':''}>各${n}枚</option>`).join('')}</select><p class="settings-help">任意のカードで保管枚数は変更できます</p></div>`;}
 function display(){const D=DCBDisplay,p=D.preferences;const radios=(name,items)=>items.map(item=>`<label class="display-option"><input type="radio" name="display-${name}" value="${item.id}" data-display-setting="${name}" ${p[name]===item.id?'checked':''}>${item.color?`<span class="display-swatch" style="--swatch:${item.color}" aria-hidden="true"></span>`:''}<span>${item.label}</span></label>`).join('');return `<fieldset class="settings-control display-control"><legend>メインカラー</legend><div class="display-options">${radios('color',D.colors)}</div></fieldset><fieldset class="settings-control display-control"><legend>テーマ</legend><div class="display-options">${radios('theme',D.themes)}</div></fieldset><div class="settings-control"><label class="settings-control-title" for="display-language">言語設定</label><select class="ui-select" id="display-language" data-display-setting="language">${D.languages.map(item=>`<option value="${item.id}" ${p.language===item.id?'selected':''}>${item.label}</option>`).join('')}</select></div>`;}
 function about(){return `<dl class="settings-data"><dt>バージョン</dt><dd>V0.1</dd><dt>収録カード</dt><dd>${DCBData.cards.length}枚</dd></dl><div class="settings-list">${row('利用規約','terms')}</div><div class="settings-control"><h2>概要</h2><p>アイカツ！アンコールのカードを管理・閲覧・交換するためのデジタルカードバインダーです。</p></div>`;}
 function terms(){return '<div class="settings-control"><p>利用規約は準備中です。</p></div>';}
 function screen(view){return `<section class="settings-page">${view==='user'?user():view==='email'?email():view==='password'?password():view==='card-registration'?registration():view==='display'?display():view==='about'?about():view==='terms'?terms():top()}</section>`;}
 async function copyId(){try{await navigator.clipboard.writeText(M.profile.id);ui.toast('コピーしました');}catch{const field=document.createElement('textarea');field.value=M.profile.id;field.style.position='fixed';field.style.opacity='0';document.body.append(field);field.select();let copied=false;try{copied=document.execCommand('copy');}catch{}field.remove();ui.toast(copied?'コピーしました':'コピーできませんでした');}}
 function showError(form,error){const field=form.querySelector('.settings-error');field.textContent=error;field.hidden=false;}
 function configure(config){ui=config;const app=document.getElementById('app');app.addEventListener('click',e=>{const button=e.target.closest('button');if(!button||!button.closest('.settings-page'))return;if(button.dataset.settingsGo){ui.go('#settings/'+button.dataset.settingsGo);return;}if(button.dataset.settings==='copy-id')copyId();if(button.dataset.settings==='logout'){M.logout();ui.go('#login');}});
 app.addEventListener('change',e=>{if(!e.target.closest('.settings-page'))return;if(e.target.dataset.displaySetting){const ok=DCBDisplay.set(e.target.dataset.displaySetting,e.target.value);ui.render();if(!ok)ui.toast('保存できませんでした');return;}if(e.target.id==='registration-mode'){DCBRegistration.setMode(e.target.value);ui.toast('登録方法を変更しました');}if(e.target.id==='bulk-retain-count'){const ok=DCBStore.setDefaultRetain(Number(e.target.value));ui.render();ui.toast(ok?'保管枚数を変更しました':'保存できませんでした');}});
 app.addEventListener('submit',e=>{if(!e.target.closest('.settings-page'))return;e.preventDefault();const form=e.target,values=new FormData(form);if(form.id==='settings-email-form'){const result=M.setEmail(values.get('email'));if(!result.ok){showError(form,result.error);return;}form.reset();ui.go('#settings/user');ui.toast('メールアドレスを変更しました（デモ）');}if(form.id==='settings-password-form'){const result=M.changePassword(values.get('current'),values.get('next'),values.get('confirmation'));if(!result.ok){showError(form,result.error);form.elements.current.value='';return;}form.reset();ui.go('#settings/user');ui.toast('パスワードを変更しました（デモ）');}});
 }
 return {configure,screen,title,parent};
})();
